11	// This file is the regression net for the independence of source-trace reports
12	// returned by TraceSources. A caller that receives a *TraceReport keeps editing
13	// it for display, may hold several reports of the same snapshot at once (and
14	// reports for other datasets that pass through the same shared intermediate),
15	// and keeps holding the input snapshot. None of those views may alias each
16	// other or the snapshot:
17	//
18	//   - editing one source record (its root name, or a name at any position of
19	//     its path, or appending a name to that path) changes only that record,
20	//     even when two paths share a prefix (T -> M -> R1 and T -> M -> R2 both
21	//     start with T, M) — the other record keeps its own root and full path;
22	//   - reordering or removing entries of the sources array never reaches the
23	//     input snapshot's dataset names or direct upstream relations;
24	//   - editing one returned report leaves every other returned report (for the
25	//     same query or for another downstream through the same intermediate)
26	//     representing the result at the moment it was obtained, and a fresh query
27	//     after the edits still reports the frozen snapshot's sources and paths;
28	//   - the snapshot itself keeps the same content identifier, graph, and export
29	//     bytes before and after tracing, including after failed queries;
30	//   - a single-element path for a root query has the same independence;
31	//   - a failed query (empty name or unknown name) keeps using the existing
32	//     error categories, returns no success report, and changes neither an
33	//     earlier report nor the snapshot;
34	//   - every independent result still obeys the existing business rules: each
35	//     root once, fewest direct relations first, equal-length ties decided
36	//     element by element from the query end in UTF-8 byte order, sources sorted
37	//     by root name, and Chinese/case/space spellings preserved verbatim.
38	
39	// traceIndependenceGraphJSON is the shared-prefix fixture: the derived
40	// datasets T and U both reach the two roots R1 and R2 through the common
41	// intermediate M, so T's two reported paths [T M R1] and [T M R2] share the
42	// prefix [T M]. X is a disconnected root and must never be reported.
43	const traceIndependenceGraphJSON = `{"datasets":[
44		{"name":"T","upstreams":["M"]},
45		{"name":"U","upstreams":["M"]},
46		{"name":"M","upstreams":["R1","R2"]},
47		{"name":"R1","upstreams":[]},
48		{"name":"R2","upstreams":[]},
49		{"name":"X","upstreams":[]}
50	]}`
51	
52	// wantIndependenceTSources is the exact source report for T, sources sorted by
53	// root name byte order with complete query-to-root paths.
54	var wantIndependenceTSources = []SourceTrace{
55		{Root: "R1", Path: []string{"T", "M", "R1"}},
56		{Root: "R2", Path: []string{"T", "M", "R2"}},
57	}
58	
59	// wantIndependenceUSources is the report for the other downstream through the
60	// same shared intermediate.
61	var wantIndependenceUSources = []SourceTrace{
62		{Root: "R1", Path: []string{"U", "M", "R1"}},
63		{Root: "R2", Path: []string{"U", "M", "R2"}},
64	}
65	
66	// wantIndependenceSnapshotDatasets is the frozen graph as the snapshot stores
67	// it: records sorted by name, roots with a non-nil empty upstream list.
68	var wantIndependenceSnapshotDatasets = []GraphDataset{
69		{Name: "M", Upstreams: []string{"R1", "R2"}},
70		{Name: "R1", Upstreams: []string{}},
71		{Name: "R2", Upstreams: []string{}},
72		{Name: "T", Upstreams: []string{"M"}},
73		{Name: "U", Upstreams: []string{"M"}},
74		{Name: "X", Upstreams: []string{}},
75	}
