77	// traceReportOf traces dataset in snap, failing the test on error.
78	func traceReportOf(t *testing.T, snap *SnapshotFile, dataset string) *TraceReport {
79		t.Helper()
80		report, err := TraceSources(snap, dataset)
81		if err != nil {
82			t.Fatalf("TraceSources(%q): %v", dataset, err)
83		}
84		return report
85	}
86	
87	// mustMarshalTraceReport renders a report the way a caller displaying it would.
88	func mustMarshalTraceReport(t *testing.T, report *TraceReport) []byte {
89		t.Helper()
90		data, err := json.Marshal(report)
91		if err != nil {
92			t.Fatalf("json.Marshal report unexpected error: %v", err)
93		}
94		return data
95	}
96	
97	// snapshotDatasetsCopy deep-copies the snapshot's dataset records so a test can
98	// compare names and direct upstreams after the caller mutates a returned
99	// report. Empty upstream lists stay non-nil, matching the snapshot's own
100	// representation.
101	func snapshotDatasetsCopy(snap *SnapshotFile) []GraphDataset {
102		datasets := make([]GraphDataset, len(snap.Graph.Datasets))
103		for i, ds := range snap.Graph.Datasets {
104			upstreams := make([]string, len(ds.Upstreams))
105			copy(upstreams, ds.Upstreams)
106			datasets[i] = GraphDataset{Name: ds.Name, Upstreams: upstreams}
107		}
108		return datasets
109	}
