package chainledger

import (
	"math/rand"
	"reflect"
	"sort"
	"testing"
)

// referenceTrace is the old full-path BFS, kept here only to differential-test
// the refactored walk on random DAGs.
func referenceTrace(dataset string, adj adjacency) []SourceTrace {
	best := map[string][]string{dataset: {dataset}}
	frontier := []string{dataset}
	for len(frontier) > 0 {
		cand := map[string][]string{}
		for _, node := range frontier {
			for _, parent := range adj[node] {
				if _, seen := best[parent]; seen {
					continue
				}
				p := append(append([]string{}, best[node]...), parent)
				if c, ok := cand[parent]; !ok {
					cand[parent] = p
				} else {
					less := false
					for i := 0; i < len(p) && i < len(c); i++ {
						if p[i] != c[i] {
							less = p[i] < c[i]
							goto decide
						}
					}
					less = len(p) < len(c)
				decide:
					if less {
						cand[parent] = p
					}
				}
			}
		}
		next := []string{}
		for n, p := range cand {
			best[n] = p
			next = append(next, n)
		}
		frontier = next
	}
	out := []SourceTrace{}
	for n, p := range best {
		if len(adj[n]) == 0 {
			out = append(out, SourceTrace{Root: n, Path: p})
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Root < out[j].Root })
	return out
}

func TestTraceRandomDifferential(t *testing.T) {
	rng := rand.New(rand.NewSource(12345))
	pool := []string{"A", "B", "C", "a", "b", "Z", "根", "中", " 中间 ", "é", "A0", "AA"}
	for iter := 0; iter < 4000; iter++ {
		n := 1 + rng.Intn(9)
		names := make([]string, n)
		for i := range names {
			names[i] = pool[rng.Intn(len(pool))]
		}
		// dedupe names
		seen := map[string]bool{}
		uniq := names[:0]
		for _, s := range names {
			if !seen[s] {
				seen[s] = true
				uniq = append(uniq, s)
			}
		}
		names = uniq
		adj := adjacency{}
		for i, name := range names {
			var parents []string
			for j := 0; j < i; j++ { // only earlier nodes -> always a DAG
				if rng.Intn(2) == 0 {
					parents = append(parents, names[j])
				}
			}
			adj[name] = parents
		}
		for _, q := range names {
			got := traceRootSources(q, adj)
			want := referenceTrace(q, adj)
			if !reflect.DeepEqual(got, want) {
				t.Fatalf("iter %d q=%q\n adj=%v\n got=%v\nwant=%v", iter, q, adj, got, want)
			}
		}
	}
}

